import { Btn, type BtnVariant } from "@/registry/p1/internal/btn";
import "./lead-capture.css";

export interface LeadCaptureProps {
  heading: string;
  subtitle: string;
  placeholder: string;
  buttonLabel: string;
  note: string;
  tone: "light" | "accent" | "dark" | "yellow";
  layout: "inline" | "stacked";
}

const BTN_BY_TONE: Record<LeadCaptureProps["tone"], BtnVariant> = {
  light: "purple",
  accent: "yellow",
  dark: "yellow",
  yellow: "primary",
};

export function LeadCaptureRender({
  heading,
  subtitle,
  placeholder,
  buttonLabel,
  note,
  tone,
  layout,
}: LeadCaptureProps) {
  return (
    <div className="p1-lead-capture p1-block">
      <div className="p1-lead-capture__card" data-tone={tone} data-layout={layout}>
        <h2 className="p1-lead-capture__heading">{heading}</h2>
        {subtitle && <p className="p1-lead-capture__subtitle">{subtitle}</p>}
        <div className="p1-lead-capture__form">
          <div className="p1-lead-capture__field">{placeholder}</div>
          <Btn variant={BTN_BY_TONE[tone]}>{buttonLabel}</Btn>
        </div>
        {note && <div className="p1-lead-capture__note">{note}</div>}
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { LeadCaptureRender, type LeadCaptureProps } from "./lead-capture";
export type { LeadCaptureProps };

export const LeadCaptureBlock: ComponentConfig<LeadCaptureProps> = {
  fields: {
    heading: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short, compelling heading. Under 6 words." },
    },
    subtitle: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1 sentence of context below the heading." },
    },
    placeholder: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Input placeholder text. E.g. you@company.com." },
    },
    buttonLabel: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "CTA button label. 1–3 words." },
    },
    note: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Trust line below the form. E.g. No spam. Unsubscribe anytime." },
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "Light", value: "light" },
        { label: "Accent", value: "accent" },
        { label: "Dark", value: "dark" },
        { label: "Yellow", value: "yellow" },
      ],
    },
    layout: {
      type: "radio" as const,
      options: [
        { label: "Inline", value: "inline" },
        { label: "Stacked", value: "stacked" },
      ],
    },
  },
  defaultProps: {
    heading: "Stay in the loop.",
    subtitle: "Occasional updates, straight to your inbox.",
    placeholder: "you@company.com",
    buttonLabel: "Subscribe",
    note: "No spam. Unsubscribe anytime.",
    tone: "accent",
    layout: "inline",
  },
  render: LeadCaptureRender,
};

export const meta = defineMeta({
  title: 'Lead Capture',
  description: 'Email capture section with heading, subtitle, placeholder text, a submit button, and a note field in inline or stacked layout; use for newsletter/lead forms.',
  categories: ["convert"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-btn"],
});

.p1-lead-capture__card {
  border-radius: var(--p1-radius-xl);
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
  padding: var(--p1-space-xl) var(--p1-space-lg);
  text-align: center;
}

.p1-lead-capture__card[data-tone="light"] {
  background-color: var(--p1-surface-subtle);
  color: var(--p1-fg-default);
}
.p1-lead-capture__card[data-tone="accent"] {
  background-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}
.p1-lead-capture__card[data-tone="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}
.p1-lead-capture__card[data-tone="yellow"] {
  background-color: var(--p1-warning);
  color: var(--p1-fg-default);
}

.p1-lead-capture__heading {
  font-size: var(--p1-text-2xl);
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-block-end: var(--p1-space-sm);
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-lead-capture__heading { font-size: var(--p1-text-3xl); }
}

.p1-lead-capture__subtitle {
  margin-block-end: var(--p1-space-lg);
  margin-inline: auto;
  max-inline-size: 36rem;
}
.p1-lead-capture__card[data-tone="light"] .p1-lead-capture__subtitle { color: var(--p1-fg-muted); }
.p1-lead-capture__card[data-tone="accent"] .p1-lead-capture__subtitle { color: var(--p1-fg-inverse-subtle); }
.p1-lead-capture__card[data-tone="dark"] .p1-lead-capture__subtitle { color: var(--p1-fg-inverse-muted); }
.p1-lead-capture__card[data-tone="yellow"] .p1-lead-capture__subtitle { color: var(--p1-accent); }

.p1-lead-capture__form {
  align-items: stretch;
  display: flex;
  gap: 0.625rem;
  margin-inline: auto;
}
.p1-lead-capture__card[data-layout="inline"] .p1-lead-capture__form {
  flex-direction: row;
  max-inline-size: 28rem;
}
.p1-lead-capture__card[data-layout="stacked"] .p1-lead-capture__form {
  flex-direction: column;
  max-inline-size: 22rem;
}

.p1-lead-capture__field {
  align-items: center;
  border-radius: var(--p1-radius-pill);
  border: 1px solid;
  color: var(--p1-fg-muted);
  display: flex;
  flex: 1;
  font-size: var(--p1-text-sm);
  padding: 0.75rem 1rem;
  text-align: start;
}
.p1-lead-capture__card[data-tone="light"] .p1-lead-capture__field {
  background-color: var(--p1-surface-default);
  border-color: var(--p1-border);
}
.p1-lead-capture__card[data-tone="accent"] .p1-lead-capture__field {
  background-color: var(--p1-input-inverse-bg-hover);
  border-color: var(--p1-border-inverse-strong);
  color: var(--p1-fg-inverse-muted);
}
.p1-lead-capture__card[data-tone="dark"] .p1-lead-capture__field {
  background-color: var(--p1-input-inverse-bg);
  border-color: var(--p1-border-inverse-strong);
  color: var(--p1-fg-inverse-muted);
}
.p1-lead-capture__card[data-tone="yellow"] .p1-lead-capture__field {
  background-color: var(--p1-surface-default);
  border-color: var(--p1-overlay-subtle);
}

.p1-lead-capture__note {
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-medium);
  margin-block-start: var(--p1-space-sm);
}
.p1-lead-capture__card[data-tone="light"] .p1-lead-capture__note { color: var(--p1-fg-muted); }
.p1-lead-capture__card[data-tone="accent"] .p1-lead-capture__note { color: var(--p1-fg-inverse-subtle); }
.p1-lead-capture__card[data-tone="dark"] .p1-lead-capture__note { color: var(--p1-fg-inverse-muted); }
.p1-lead-capture__card[data-tone="yellow"] .p1-lead-capture__note { color: var(--p1-accent); }

